package com.library.model;

import com.library.enums.NotificationType;

import java.time.LocalDateTime;
import java.util.Objects;

/**
 * Notification record generated by the system for student users.
 */
public class Notification {
    private final String id;
    private final String studentId;
    private final NotificationType type;
    private final String message;
    private boolean read;
    private final LocalDateTime createdAt;

    public Notification(String id, String studentId, NotificationType type,
                        String message, boolean read, LocalDateTime createdAt) {
        this.id = Objects.requireNonNull(id, "notification id");
        this.studentId = Objects.requireNonNull(studentId, "student id");
        this.type = Objects.requireNonNull(type, "notification type");
        this.message = Objects.requireNonNull(message, "message");
        this.read = read;
        this.createdAt = createdAt == null ? LocalDateTime.now() : createdAt;
    }

    public String getId() {
        return id;
    }

    public String getStudentId() {
        return studentId;
    }

    public NotificationType getType() {
        return type;
    }

    public String getMessage() {
        return message;
    }

    public boolean isRead() {
        return read;
    }

    public void markRead() {
        this.read = true;
    }

    public LocalDateTime getCreatedAt() {
        return createdAt;
    }
}
